def calculate_simple_interest(principal, rate, time):
    """Calculates the simple interest.

    Args:
        principal (float): The initial amount of money.
        rate (float): The annual interest rate as a percentage.
        time (int): The time period in years.

    Returns:
        float: The calculated simple interest.
    """
    return principal * (rate / 100) * time

def get_principal_input():
    """Prompts the user to enter the principal amount.

    Returns:
        float: The principal amount entered by the user.
    """
    while True:
        try:
            principal = float(input("Enter principal amount: "))
            if principal < 0:
                print("Principal cannot be negative. Please try again.")
            else:
                return principal
        except ValueError:
            print("Invalid input. Please enter a number.")

def get_rate_input():
    """Prompts the user to enter the annual interest rate.

    Returns:
        float: The interest rate entered by the user.
    """
    while True:
        try:
            rate = float(input("Enter annual interest rate (as a percentage): "))
            if rate < 0:
                print("Rate cannot be negative. Please try again.")
            else:
                return rate
        except ValueError:
            print("Invalid input. Please enter a number.")

def get_time_input():
    """Prompts the user to enter the time period in years.

    Returns:
        int: The time period in years entered by the user.
    """
    while True:
        try:
            time = int(input("Enter time period (in years): "))
            if time < 0:
                print("Time cannot be negative. Please try again.")
            else:
                return time
        except ValueError:
            print("Invalid input. Please enter an integer.")

def main():
    """Main function to run the simple interest calculation program."""
    principal_amount = get_principal_input()
    interest_rate = get_rate_input()
    time_period = get_time_input()

    interest = calculate_simple_interest(principal_amount, interest_rate, time_period)
    print(f"The simple interest is: {interest:.2f}")

if __name__ == "__main__":
    main()

def is_even(number: int) -> bool:
    """Checks if a given integer is an even number.

    Args:
        number: The integer to check.

    Returns:
        True if the number is even, False otherwise.
    """
    return number % 2 == 0

def get_number_from_user() -> int:
    """Prompts the user to enter an integer and returns it.

    Returns:
        The integer entered by the user.
    """
    while True:
        try:
            user_input = input("Enter an integer: ")
            return int(user_input)
        except ValueError:
            print("Invalid input. Please enter an integer.")

def display_result(number: int, even_status: bool):
    """Prints whether the given number is even or odd.

    Args:
        number: The integer that was checked.
        even_status: A boolean indicating if the number is even.
    """
    if even_status:
        print(f"The number {number} is even.")
    else:
        print(f"The number {number} is odd.")

def main():
    """Main function to execute the even/odd checker program."""
    num = get_number_from_user()
    result = is_even(num)
    display_result(num, result)

if __name__ == "__main__":
    main()

def common_keys(dict1: dict, dict2: dict) -> set:
    """Finds keys present in both input dictionaries.

    Args:
        dict1: The first dictionary.
        dict2: The second dictionary.

    Returns:
        A set containing keys that exist in both dict1 and dict2.
    """
    return set(dict1.keys()) & set(dict2.keys())

def _example_usage():
    """Demonstrates the usage of the common_keys function."""
    d1 = {'a': 1, 'b': 2, 'c': 3}
    d2 = {'b': 3, 'c': 4, 'd': 5}
    d3 = {'x': 1}
    d4 = {'y': 2}

    result1 = common_keys(d1, d2)
    result2 = common_keys(d3, d4)
    result3 = common_keys({}, d1)

    print(f"Common keys of {d1} and {d2}: {result1}")
    print(f"Common keys of {d3} and {d4}: {result2}")
    print(f"Common keys of {{}} and {d1}: {result3}")

def _test_empty_dicts():
    """Tests common_keys with empty dictionaries.

    Returns:
        bool: True if the test passes, False otherwise.
    """
    return common_keys({}, {}) == set()

def _test_no_common_keys():
    """Tests common_keys when there are no common keys.

    Returns:
        bool: True if the test passes, False otherwise.
    """
    return common_keys({'a': 1}, {'b': 2}) == set()

def _test_all_common_keys():
    """Tests common_keys when all keys are common.

    Returns:
        bool: True if the test passes, False otherwise.
    """
    return common_keys({'a': 1, 'b': 2}, {'a': 3, 'b': 4}) == {'a', 'b'}

if __name__ == '__main__':
    _example_usage()
    print(f"Test empty dicts: {_test_empty_dicts()}")
    print(f"Test no common keys: {_test_no_common_keys()}")
    print(f"Test all common keys: {_test_all_common_keys()}")
    print(f"Specific test: {common_keys({'a':1, 'b':2}, {'b':3, 'c':4}) == {'b'}}")
    print(f"Specific test: {common_keys({'x':1}, {'y':2}) == set()}")
